// SCREEN NAV
// ══════════════════════════════════════
function showScreen(id){document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));document.getElementById(id).classList.add('active');}
function showLanding(){showScreen('landing');}
function showSelect(){
  document.getElementById('combat-overlay').classList.remove('visible');
  document.getElementById('result-overlay').classList.remove('visible');
  showScreen('select-screen');
  renderMapGrid();
  renderSelectGrid();
  stopBattleMusic();
}

const MAP_INFO=[
  {id:'freljord',icon:'❄️',name:'Freljord',desc:'Forêt des Murmures Gelés — terrain enneigé, ruines anciennes.'},
  {id:'demacia',icon:'🏛️',name:'Demacia',desc:'Cité de Pierre Céleste — plazas, champs, arbres de pétricite (-30% dégâts à proximité).'},
];

function renderMapGrid(){
  const g=document.getElementById('map-grid');
  g.innerHTML=MAP_INFO.map(m=>{
    const sel=currentMapId===m.id;
    return `<div class="map-card${sel?' selected':''}" onclick="selectMap('${m.id}')">
      <div class="map-card-badge">✓</div>
      <span class="map-card-icon">${m.icon}</span>
      <div class="map-card-name">${m.name}</div>
      <div class="map-card-desc">${m.desc}</div>
    </div>`;
  }).join('');
  document.getElementById('select-header-sub').textContent=MAPS[currentMapId].name;
}

function selectMap(id){
  currentMapId=id;
  renderMapGrid();
}

function renderSelectGrid(){
  const g=document.getElementById('champ-grid');
  g.innerHTML=CHAMPS.map(c=>{
    const i=selChamps.indexOf(c.id),sel=i>=0,dis=selChamps.length>=4&&!sel;
    return `<div class="champ-card${sel?' selected':''}${dis?' maxed':''}" onclick="toggleChamp('${c.id}')">
      <div class="card-sel-badge">✓</div>${sel?`<div class="card-num">${i+1}</div>`:''}
      ${c.portrait?`<img src="${c.portrait}" style="position:absolute;inset:0;width:100%;height:60%;object-fit:cover;object-position:top;border-radius:4px;opacity:0.35;pointer-events:none;">`:``}
      <span class="card-emoji" style="position:relative">${c.icon?`<img src="${c.icon}" style="width:36px;height:24px;object-fit:contain;filter:brightness(0) invert(1);display:block;margin:0 auto;">`:c.emoji}</span>
      <div class="card-name" style="position:relative">${c.name}</div><div class="card-role" style="position:relative">${c.role}</div>
      <div class="card-desc">${c.desc}</div>
      <div class="card-stats">
        <span class="stat-pill sp-hp">❤️${c.hp}</span>
        <span class="stat-pill sp-mp">💧${c.maxMp}</span>
        <span class="stat-pill sp-atk">⚔️${c.atk}</span>
        <span class="stat-pill sp-rng">↔️${c.range}c</span>
      </div>
    </div>`;
  }).join('');
  document.getElementById('sel-display').textContent=selChamps.length;
  document.getElementById('launch-btn').disabled=selChamps.length!==4;
}

function toggleChamp(id){
  const i=selChamps.indexOf(id);
  if(i>=0)selChamps.splice(i,1);
  else if(selChamps.length<4)selChamps.push(id);
  renderSelectGrid();
}

