const MAPS={
  freljord:{name:'Freljord — Forêt des Murmures Gelés',rows:FRELJORD_ROWS,
    key:{S:'snow',F:'forest',R:'ruin',I:'ice',M:'mountain',W:'water',B:'base',' ':'snow'}},
  demacia:{name:'Demacia — Cité de Pierre Céleste',rows:DEMACIA_ROWS,
    key:{G:'grass',E:'field',W:'wall',P:'plaza',R:'ruin',N:'petricite',F:'forest',B:'base',' ':'grass'}},
};
let currentMapId='freljord';
let petriciteCells=[]; // [{row,col}] positions of petricite trees, for damage-reduction aura

function genTerrain(){
  grid=[];
  const mapDef=MAPS[currentMapId];
  const rows=mapDef.rows,key=mapDef.key;
  petriciteCells=[];
  for(let r=0;r<ROWS;r++){
    grid[r]=[];
    const row=rows[r]||'';
    for(let c=0;c<COLS;c++){
      const ch=row[c]||Object.keys(key).find(k=>k===' ')||'G';
      const type=key[ch]||key[' ']||'grass';
      grid[r][c]={type,unit:null};
      if(type==='petricite')petriciteCells.push({row:r,col:c});
    }
  }
}

// Returns the damage multiplier reduction (0 to 0.3) if a cell is within radius 2 of any petricite tree
function petriciteReduction(row,col){
  for(const p of petriciteCells){
    const d=Math.abs(p.row-row)+Math.abs(p.col-col);
    if(d<=2)return 0.3; // -30% damage near petricite trees
  }
  return 0;
}

