// GAME INIT
// ══════════════════════════════════════
function dc(x){return JSON.parse(JSON.stringify(x));}
function getU(id){return units.find(u=>u.id===id);}
// Clears all grid cells occupied by a unit (handles multi-cell big units)
function clearUnitCells(u){
  if(u.isBig&&u.occupies){u.occupies.forEach(([r,c])=>{if(grid[r]&&grid[r][c])grid[r][c].unit=null;});}
  else if(grid[u.row]&&grid[u.row][u.col])grid[u.row][u.col].unit=null;
}
// Removes a dead unit from units[] and clears its grid cells
function removeUnit(u){clearUnitCells(u);units=units.filter(x=>x.id!==u.id);}
function allies(){return units.filter(u=>u.team==='ally'&&u.hp>0);}
function enemies(){return units.filter(u=>u.team==='enemy'&&u.hp>0);}
function auraBonus(){
  // Cheffe bandit's +5 ATK aura only applies on Freljord
  if(currentMapId!=='freljord')return 0;
  const b=getU('boss');return(b&&b.hp>0)?5:0;
}
function addLog(m,t=''){logs.unshift({m,t});if(logs.length>60)logs.pop();renderSidebar();}

function startGame(){
  if(selChamps.length!==4)return;
  genTerrain();units=[];shields={};charges={};logs=[];selUnit=null;mvCells=[];atkCells=[];needles=1;turn=1;phase='ally';cState=null;c4Traps=[];pendingC4=false;wolfId=0;ultUsed={};staseZones=[];pendingStase=false;pendingTranscendTarget=null;iceWalls=[];abilityCooldowns={};
  const aS=[[28,2],[28,4],[27,3],[29,3]];
  selChamps.forEach((id,i)=>{const u=dc(CHAMPS.find(c=>c.id===id));u.row=aS[i][0];u.col=aS[i][1];u.effects=[];u.hasMoved=false;u.hasActed=false;units.push(u);grid[u.row][u.col].unit=u.id;});
  // Spawn enemies — different set and positions per map
  if(currentMapId==='demacia'){
    // Demacia enemies spawn in the city zone (north) — plazas and ruins
    const dS=[[3,4],[5,6],[4,2],[1,8],[1,14],[2,10],[5,3],[2,6]];
    DEMACIA_ENEMIES.forEach((def,i)=>{
      const u=dc(def);const[r,c]=dS[i]||[i+1,5];
      // Find nearest free walkable cell around preferred position
      let placed=false;
      for(let dr=-2;dr<=2&&!placed;dr++)for(let dc2=-2;dc2<=2&&!placed;dc2++){
        const nr=r+dr,nc=c+dc2;
        if(nr>=0&&nr<ROWS&&nc>=0&&nc<COLS&&!grid[nr][nc].unit&&grid[nr][nc].type!=='mountain'&&grid[nr][nc].type!=='water'&&grid[nr][nc].type!=='wall'){
          u.row=nr;u.col=nc;grid[nr][nc].unit=u.id;placed=true;
        }
      }
      u.effects=[];u.hasMoved=false;u.hasActed=false;units.push(u);
    });
  } else {
    // Freljord enemies
    const eS=[[3,27],[5,25],[4,29],[1,28],[2,29],[5,28],[1,27]];
    ENEMIES.forEach((def,i)=>{const u=dc(def);u.row=eS[i][0];u.col=eS[i][1];u.effects=[];u.hasMoved=false;u.hasActed=false;units.push(u);grid[u.row][u.col].unit=u.id;});
  }
  // Freljord-exclusive: spawn the ice mage
  if(currentMapId==='freljord'){
    const mg=dc(FRELJORD_EXTRA_ENEMIES[0]);
    const trySpots=[[0,26],[1,26],[2,28],[0,28],[0,29]];
    let placed=false;
    for(const[r,c] of trySpots){if(!grid[r][c].unit&&grid[r][c].type!=='mountain'&&grid[r][c].type!=='wall'){mg.row=r;mg.col=c;grid[r][c].unit=mg.id;placed=true;break;}}
    if(!placed){mg.row=5;mg.col=26;grid[5][26].unit=mg.id;}
    mg.effects=[];mg.hasMoved=false;mg.hasActed=false;units.push(mg);
  }
  document.getElementById('turn-lbl').textContent='Tour 1';
  document.getElementById('phase-lbl').textContent='Phase : Alliés';
  document.getElementById('map-lbl').textContent=MAP_INFO.find(m=>m.id===currentMapId).icon+' '+MAP_INFO.find(m=>m.id===currentMapId).name;
  document.getElementById('end-btn').disabled=false;
  document.getElementById('sel-lbl').textContent='Cliquez sur un champion';
  document.getElementById('result-overlay').classList.remove('visible');
  showScreen('game-screen');
  draw();renderSidebar();renderSkillBar(null);
  if(currentMapId==='demacia'){
    addLog('⚔️ Les soldats de Demacia défendent la cité !','l-sys');
    addLog('🚩 Le porte-bannière renforce ses alliés à proximité (+40% DEF)','l-sys');
    addLog('🌳 Les arbres de pétricite réduisent les dégâts de 30% à proximité','l-sys');
  } else {
    addLog('⚔️ Embuscade de bandits !','l-sys');
    addLog('👹 La cheffe galvanise ses hommes (+5 ATK)','l-sys');
  }
  addLog('💧 +8 PM par tour pour tous','l-mp');
  setTimeout(()=>{const mw=document.getElementById('map-wrap');mw.scrollLeft=0;mw.scrollTop=ROWS*CELL-mw.clientHeight;},100);
  playBattleMusic();
}
function restartGame(){document.getElementById('result-overlay').classList.remove('visible');startGame();}

// ══════════════════════════════════════
// COMBAT MATH
// ══════════════════════════════════════
function roll(acc,ec=0){const r=Math.random()*100;if(r>acc)return'miss';if(r<(6+ec))return'crit';return'hit';}
function accCls(a){return a>=80?'acc-hi':a>=55?'acc-md':'acc-lo';}
function accLbl(a){return a>=80?'Précis':a>=55?'Risqué':'Dangereux';}
function resolveHit(att,ab,tgt,isCrit){
  const acc=ab.acc||att.acc||80;
  const r=roll(acc,isCrit?15:5);
  if(r==='miss')return{result:'miss',dmg:0};
  // Full invulnerability (Corear's Transcendance windup) — blocks all damage entirely
  if(shields[tgt.id]==='invuln')return{result:'hit',dmg:0,blocked:true};
  let dmg=Math.floor(att.atk*(ab.power||1)*DMG*(.88+Math.random()*.25));
  if(r==='crit')dmg=Math.floor(dmg*2);
  // Bannière aura: if a porte-bannière ally is within radius 2, target DEF is boosted by 40%
  const effectiveDef=(tgt.def||0)*banniereAuraBonus(tgt);
  dmg=Math.max(1,dmg-Math.floor(effectiveDef*.35));
  // Cavalier 10% damage reduction
  if(tgt.dmgReduction)dmg=Math.max(1,Math.floor(dmg*(1-tgt.dmgReduction)));
  // Petricite trees (Demacia) reduce damage taken by units standing near them
  if(typeof tgt.row==='number'&&typeof tgt.col==='number'){
    const reduction=petriciteReduction(tgt.row,tgt.col);
    if(reduction>0)dmg=Math.max(1,Math.floor(dmg*(1-reduction)));
  }
  if(shields[tgt.id]){dmg=Math.floor(dmg*.45);delete shields[tgt.id];}
  return{result:r,dmg};
}

// Returns the DEF multiplier from the porte-bannière aura (1.4 if within range, 1.0 otherwise)
function banniereAuraBonus(tgt){
  const banner=getU('banner');
  if(!banner||banner.hp<=0)return 1.0;
  const d=Math.abs(tgt.row-banner.row)+Math.abs(tgt.col-banner.col);
  return d<=2?1.4:1.0;
}

// ══════════════════════════════════════
// MOVEMENT
// ══════════════════════════════════════
// Checks if a cell is currently frozen by Corear's Stase Corrompue (impassable for everyone)
function isStaseZone(r,c){
  return staseZones.some(z=>z.row===r&&z.col===c);
}

function getMovCells(u){
  if(u.hasMoved||u.team!==phase)return[];
  // Immobilize (Chloropouvoir roots) — blocks all movement
  if((u.effects||[]).some(e=>e.type==='immobilize'))return[];
  if(u.isBig)return getBigMovCells(u);
  // mage_slow reduces MOV by 1 (minimum 0)
  const slowMov=Math.max(0,u.mov-((u.effects||[]).some(e=>e.type==='mage_slow')?1:0));
  const vis=new Set([`${u.row},${u.col}`]),q=[[u.row,u.col,slowMov]],cells=[];
  while(q.length){
    const[r,c,rem]=q.shift();
    if(rem<slowMov)cells.push([r,c]);
    if(!rem)continue;
    [[r-1,c],[r+1,c],[r,c-1],[r,c+1]].forEach(([nr,nc])=>{
      if(nr<0||nr>=ROWS||nc<0||nc>=COLS)return;
      const k=`${nr},${nc}`;if(vis.has(k))return;
      if(grid[nr][nc].type==='mountain'||grid[nr][nc].type==='water'||grid[nr][nc].type==='wall')return;
      if(isStaseZone(nr,nc))return;
      if(iceWalls.some(w=>w.row===nr&&w.col===nc))return; // ice wall blocks movement
      if(grid[nr][nc].unit){const o=getU(grid[nr][nc].unit);if(o&&o.team===u.team)return;}
      vis.add(k);q.push([nr,nc,rem-1]);
    });
  }
  return cells;
}

// Checks if a 2x2 block anchored at (r,c) is fully walkable and free (ignoring the unit's own current cells)
function canPlaceBig(u,r,c){
  if(r<0||r+1>=ROWS||c<0||c+1>=COLS)return false;
  for(let dr=0;dr<2;dr++)for(let dc2=0;dc2<2;dc2++){
    const rr=r+dr,cc=c+dc2;
    const t=grid[rr][cc].type;
    if(t==='mountain'||t==='water'||t==='wall')return false;
    if(isStaseZone(rr,cc))return false;
    const occ=grid[rr][cc].unit;
    if(occ&&occ!==u.id)return false; // occupied by another unit (not self)
  }
  return true;
}

// BFS movement range for 2x2 "big" units (anchor = top-left cell)
function getBigMovCells(u){
  const vis=new Set([`${u.row},${u.col}`]),q=[[u.row,u.col,u.mov]],cells=[];
  while(q.length){
    const[r,c,rem]=q.shift();
    if(rem<u.mov)cells.push([r,c]);
    if(!rem)continue;
    [[r-1,c],[r+1,c],[r,c-1],[r,c+1]].forEach(([nr,nc])=>{
      const k=`${nr},${nc}`;if(vis.has(k))return;
      if(!canPlaceBig(u,nr,nc))return;
      vis.add(k);q.push([nr,nc,rem-1]);
    });
  }
  return cells;
}
// Bresenham line: checks if any ice wall cell blocks the line between (r1,c1) and (r2,c2)
function iceWallBlocksLOS(r1,c1,r2,c2){
  if(iceWalls.length===0)return false;
  let x=c1,y=r1;
  const dx=Math.abs(c2-c1),dy=Math.abs(r2-r1);
  const sx=c1<c2?1:-1,sy=r1<r2?1:-1;
  let err=dx-dy;
  while(true){
    if(x===c2&&y===r2)break;
    if(iceWalls.some(w=>w.row===y&&w.col===x))return true;
    const e2=2*err;
    if(e2>-dy){err-=dy;x+=sx;}
    if(e2<dx){err+=dx;y+=sy;}
  }
  return false;
}

function getAtkCells(u){
  const cells=[];
  for(let dr=-u.range;dr<=u.range;dr++)for(let dc2=-u.range;dc2<=u.range;dc2++){
    const d=Math.abs(dr)+Math.abs(dc2);if(!d||d>u.range)continue;
    const nr=u.row+dr,nc=u.col+dc2;
    if(nr<0||nr>=ROWS||nc<0||nc>=COLS)continue;
    if(u.range>1&&iceWallBlocksLOS(u.row,u.col,nr,nc))continue; // ice walls block ranged LOS (not melee)
    if(grid[nr][nc].unit){const o=getU(grid[nr][nc].unit);if(o&&o.team!==u.team&&o.hp>0)cells.push([nr,nc]);}
  }
  return cells;
}

// ══════════════════════════════════════
// DRAW
// ══════════════════════════════════════
function draw(){
  ctx.clearRect(0,0,canvas.width,canvas.height);
  const mvS=new Set(mvCells.map(([r,c])=>`${r},${c}`));
  const akS=new Set(atkCells.map(([r,c])=>`${r},${c}`));
  for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){
    const t=grid[r][c].type,x=c*CELL,y=r*CELL;
    // Checkerboard effect
    ctx.fillStyle=(r+c)%2===0?TC[t]:TC2[t];
    ctx.fillRect(x,y,CELL,CELL);
    const k=`${r},${c}`;
    if(selUnit&&grid[r][c].unit===selUnit.id){ctx.fillStyle='rgba(201,168,76,.18)';ctx.fillRect(x,y,CELL,CELL);}
    else if(akS.has(k)){ctx.fillStyle='rgba(192,57,43,.25)';ctx.fillRect(x,y,CELL,CELL);}
    else if(mvS.has(k)){ctx.fillStyle='rgba(42,109,181,.2)';ctx.fillRect(x,y,CELL,CELL);}
    else if(pendingC4&&selUnit&&Math.abs(r-selUnit.row)+Math.abs(c-selUnit.col)<=10){ctx.fillStyle='rgba(255,140,60,.12)';ctx.fillRect(x,y,CELL,CELL);}
    else if(pendingStase&&selUnit&&Math.abs(r-selUnit.row)+Math.abs(c-selUnit.col)<=5){ctx.fillStyle='rgba(140,40,200,.14)';ctx.fillRect(x,y,CELL,CELL);}
    else if(isStaseZone(r,c)){ctx.fillStyle='rgba(90,20,140,.32)';ctx.fillRect(x,y,CELL,CELL);}
    else{const banner=getU('banner');if(banner&&banner.hp>0&&Math.abs(r-banner.row)+Math.abs(c-banner.col)<=2){ctx.fillStyle='rgba(255,215,0,.08)';ctx.fillRect(x,y,CELL,CELL);}}
    // Grid lines
    ctx.strokeStyle='rgba(255,255,255,.04)';ctx.lineWidth=.5;ctx.strokeRect(x,y,CELL,CELL);
    // Terrain icon
    if(!grid[r][c].unit&&TI[t]){ctx.font=`${CELL*.4}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.globalAlpha=.25;ctx.fillStyle='#fff';ctx.fillText(TI[t],x+CELL/2,y+CELL/2);ctx.globalAlpha=1;}
    if(isStaseZone(r,c)){ctx.font=`${CELL*.45}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='rgba(200,120,255,.7)';ctx.fillText('🌀',x+CELL/2,y+CELL/2);}
    // Move overlay dots
    if(mvS.has(k)&&!grid[r][c].unit){ctx.fillStyle='rgba(42,109,181,.5)';ctx.beginPath();ctx.arc(x+CELL/2,y+CELL/2,3,0,Math.PI*2);ctx.fill();}
  }
  // Petricite damage-reduction aura zones (Demacia)
  if(petriciteCells.length){
    for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){
      if(petriciteReduction(r,c)>0){
        const x=c*CELL,y=r*CELL;
        ctx.fillStyle='rgba(93,202,165,.08)';ctx.fillRect(x,y,CELL,CELL);
      }
    }
    // Tree trunk highlight + small radius ring marker
    petriciteCells.forEach(p=>{
      const x=p.col*CELL,y=p.row*CELL;
      ctx.strokeStyle='rgba(93,202,165,.45)';ctx.lineWidth=1;
      ctx.beginPath();ctx.arc(x+CELL/2,y+CELL/2,CELL*1.9,0,Math.PI*2);ctx.stroke();
    });
  }
  // Draw C4 traps
  c4Traps.forEach(t=>{
    const x=t.col*CELL,y=t.row*CELL;
    ctx.fillStyle='rgba(255,80,30,.15)';ctx.fillRect(x+3,y+3,CELL-6,CELL-6);
    ctx.strokeStyle='rgba(255,120,50,.6)';ctx.lineWidth=1;ctx.strokeRect(x+3,y+3,CELL-6,CELL-6);
    ctx.font=`${CELL*.38}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.globalAlpha=.85;ctx.fillStyle='#fff';ctx.fillText('💣',x+CELL/2,y+CELL/2);ctx.globalAlpha=1;
  });
  // Draw ice walls
  iceWalls.forEach(w=>{
    const x=w.col*CELL,y=w.row*CELL;
    ctx.fillStyle='rgba(150,220,255,.35)';ctx.fillRect(x,y,CELL,CELL);
    ctx.strokeStyle='rgba(100,180,255,.8)';ctx.lineWidth=1.5;ctx.strokeRect(x+1,y+1,CELL-2,CELL-2);
    ctx.font=`${CELL*.48}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.globalAlpha=.9;ctx.fillStyle='#fff';ctx.fillText('🧊',x+CELL/2,y+CELL/2);ctx.globalAlpha=1;
  });

  units.filter(u=>u.hp>0).forEach(u=>{
    const sizeMult=u.isBig?2:1;
    const x=u.col*CELL,y=u.row*CELL,w=CELL*sizeMult,h=CELL*sizeMult,isSel=selUnit&&selUnit.id===u.id;
    let bg;
    if(u.team==='ally')bg=u.isMech?'rgba(70,90,150,.92)':u.isBig?'rgba(120,100,40,.9)':u.isWolf?'rgba(70,70,110,.85)':u.hasActed?'rgba(60,55,100,.85)':'rgba(91,79,168,.9)';
    else if(u.isBoss)bg='rgba(160,60,20,.95)';
    else if(u.isElite)bg='rgba(100,60,10,.9)';
    else bg='rgba(139,26,26,.85)';
    ctx.fillStyle=bg;rRect(x+2,y+2,w-4,h-4,3);
    // Selection ring
    if(isSel){ctx.strokeStyle='rgba(201,168,76,.9)';ctx.lineWidth=2;rRect(x+1,y+1,w-2,h-2,4);ctx.stroke();}
    // Boss aura ring
    if(u.isBoss&&u.hp>0){ctx.strokeStyle='rgba(201,168,76,.3)';ctx.lineWidth=1.5;rRect(x,y,w,h,5);ctx.stroke();}
    // Porte-bannière: golden aura ring
    if(u.isBanner&&u.hp>0){ctx.strokeStyle='rgba(255,220,60,.6)';ctx.lineWidth=2;rRect(x-1,y-1,w+2,h+2,6);ctx.stroke();}
    // Cavalier: silver damage-reduction badge
    if(u.dmgReduction&&u.hp>0){ctx.fillStyle='rgba(160,200,255,.85)';ctx.font=`${h*.22}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('🛡️',x+4,y+h-13);}
    // Emoji
    ctx.font=`${h*.42}px serif`;ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.shadowColor='rgba(0,0,0,.7)';ctx.shadowBlur=4;
    ctx.fillStyle='#fff';ctx.fillText(u.emoji,x+w/2,y+h/2-2);ctx.shadowBlur=0;
    // HP bar
    const hp=u.hp/u.maxHp,mp=u.maxMp?u.mp/u.maxMp:0;
    ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(x+2,y+h-8,w-4,3);
    ctx.fillStyle=hp>.5?'#1D8A60':hp>.25?'#C17D0E':'#9B2020';
    ctx.fillRect(x+2,y+h-8,Math.floor((w-4)*hp),3);
    // MP bar
    if(u.maxMp){
      ctx.fillStyle='rgba(0,0,0,.4)';ctx.fillRect(x+2,y+h-4,w-4,3);
      ctx.fillStyle='#1A5DA0';ctx.fillRect(x+2,y+h-4,Math.floor((w-4)*mp),3);
    }
    // Indicators
    if(shields[u.id]){ctx.fillStyle='#60A5FA';ctx.beginPath();ctx.arc(x+4,y+5,2.5,0,Math.PI*2);ctx.fill();}
    if((charges[u.id]||0)>=3){ctx.fillStyle='#EF9F27';ctx.beginPath();ctx.arc(x+w-4,y+5,2.5,0,Math.PI*2);ctx.fill();}
    if(u.hasActed&&u.team==='ally'){ctx.fillStyle='rgba(201,168,76,.7)';ctx.font=`${h*.2}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('✓',x+w-5,y+h-11);}
  });
}
function rRect(x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.lineTo(x+w-r,y);ctx.quadraticCurveTo(x+w,y,x+w,y+r);ctx.lineTo(x+w,y+h-r);ctx.quadraticCurveTo(x+w,y+h,x+w-r,y+h);ctx.lineTo(x+r,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-r);ctx.lineTo(x,y+r);ctx.quadraticCurveTo(x,y,x+r,y);ctx.closePath();ctx.fill();}

// ══════════════════════════════════════
// SIDEBAR
// ══════════════════════════════════════
function renderSidebar(){
  const aura=auraBonus();
  document.getElementById('ally-list').innerHTML=allies().map(u=>{
    const hp=(u.hp/u.maxHp)*100,mp=u.maxMp?(u.mp/u.maxMp)*100:0,hc=hp>50?'#1D8A60':hp>25?'#C17D0E':'#9B2020';
    const isSel=selUnit&&selUnit.id===u.id;
    return `<div class="sb-chip${isSel?' active':''}${u.hasActed?' spent':''}" onclick="selectU('${u.id}')">
      <span class="sb-emoji">${u.emoji}</span>
      <div class="sb-info"><div class="sb-name">${u.name}${u.hasActed?' ✓':''}</div>
      <div class="sb-bars">
        <div class="sb-bar"><div style="width:${hp}%;height:100%;border-radius:1px;background:${hc};"></div></div>
        <div class="sb-bar"><div style="width:${mp}%;height:100%;border-radius:1px;background:#1A5DA0;"></div></div>
      </div></div></div>`;
  }).join('');
  document.getElementById('enemy-list').innerHTML=enemies().map(u=>{
    const hp=(u.hp/u.maxHp)*100,mp=(u.mp/u.maxMp)*100;
    const ic=u.isBoss?'👑':u.isBanner?'🚩':u.isElite?'⭐':u.aiType==='crossbow'?'🎯':u.aiType==='captain'?'🛡️':u.aiType==='ranged'?'🏹':'🗡️';
    return `<div class="sb-chip enemy-chip${u.isBoss?' boss-chip':''}">
      <span class="sb-emoji">${u.emoji}</span>
      <div class="sb-info">
        <div class="sb-name">${ic}${u.name}${u.isBoss&&u.hp>0?' ✦':''}</div>
        <div class="sb-type">❤️${u.hp}${!u.isBoss&&aura>0?' ⚔️'+(u.atk+aura)+'<span style="color:#EF9F27;">(+'+aura+')</span>':''}</div>
        <div class="sb-bars">
          <div class="sb-bar"><div style="width:${hp}%;height:100%;border-radius:1px;background:#8B1A1A;"></div></div>
          <div class="sb-bar"><div style="width:${mp}%;height:100%;border-radius:1px;background:#1A5DA0;"></div></div>
        </div>
      </div></div>`;
  }).join('');
  document.getElementById('log-box').innerHTML=logs.slice(0,20).map(l=>`<div class="log-entry ${l.t}">${l.m}</div>`).join('');
}

// ══════════════════════════════════════
// SKILL BAR
// ══════════════════════════════════════
function renderSkillBar(u){
  const noSel=document.getElementById('no-sel'),detail=document.getElementById('unit-detail');
  if(!u){noSel.style.display='flex';detail.style.display='none';document.getElementById('sk-header').textContent='— Aucun champion sélectionné —';document.getElementById('skills-grid').innerHTML='<div class="acted-msg-g">Cliquez sur un champion</div>';return;}
  noSel.style.display='none';detail.style.display='block';
  document.getElementById('up-em').textContent=u.emoji;
  document.getElementById('up-nm').textContent=u.name;
  document.getElementById('up-rl').textContent=u.role||(u.isWolf?'Loup invoqué':u.isBig?'Invocation':u.isMech?'Exosuit':'');
  const upPortrait=document.getElementById('up-portrait');
  if(upPortrait){if(u.portrait){upPortrait.style.backgroundImage=`url(${u.portrait})`;upPortrait.style.display='block';}else{upPortrait.style.display='none';}}
  const hpP=(u.hp/u.maxHp)*100,hc=hpP>50?'#1D8A60':hpP>25?'#C17D0E':'#9B2020';
  document.getElementById('up-hp').style.cssText=`width:${hpP}%;background:${hc};`;
  document.getElementById('up-hpv').textContent=`${u.hp}/${u.maxHp}`;
  document.getElementById('up-mp').style.width=(u.maxMp?(u.mp/u.maxMp)*100:0)+'%';
  document.getElementById('up-mpv').textContent=`${u.mp||0}/${u.maxMp||0}`;
  document.getElementById('up-atk').textContent=u.atk;
  document.getElementById('up-def').textContent=u.def;
  document.getElementById('up-spd').textContent=u.spd;
  document.getElementById('up-mov').textContent=u.mov;
  document.getElementById('up-acc').textContent=u.acc;
  document.getElementById('up-rng').textContent=u.range;
  document.getElementById('up-pas').textContent='⚡ '+(u.passif||'Unité automatique — agit seule à la fin du tour');
  document.getElementById('up-acted').style.display=u.hasActed?'block':'none';

  if(phase!=='ally'){document.getElementById('sk-header').textContent='⏳ Phase ennemie...';document.getElementById('skills-grid').innerHTML='<div class="acted-msg-g">Attendez votre tour</div>';return;}

  // Auto-controlled summons (wolves only) have no manual actions
  if(u.isWolf){
    document.getElementById('sk-header').textContent=`${u.name} — Unité automatique`;
    document.getElementById('skills-grid').innerHTML=`<div class="acted-msg-g">Ce loup attaque seul à la fin du tour.</div>`;
    return;
  }
  // Cacahuète is player-controlled but has no abilities — just basic move + attack
  if(u.isBig){
    if(u.hasActed){document.getElementById('sk-header').textContent=`✓ ${u.name} a déjà agi`;document.getElementById('skills-grid').innerHTML='<div class="acted-msg-g">Cacahuète a déjà agi ce tour.</div>';return;}
    const hasE=getAtkCells(u).length>0;
    document.getElementById('sk-header').textContent=`${u.name} — Invocation contrôlable`;
    document.getElementById('skills-grid').innerHTML=`<button class="sk-btn basic-sk" onclick="useAction(0)">
      <span class="sk-type">BASIQUE</span>
      <span class="sk-name">Coup de bec géant</span>
      <span class="sk-desc">Attaque puissante au corps à corps.</span>
      <span class="sk-acc acc-hi">🎯${u.acc}% Précis</span>
      <span class="sk-cost">Gratuit${!hasE?' · hors portée':''}</span>
    </button>`;
    return;
  }

  if(u.hasActed){document.getElementById('sk-header').textContent=`✓ ${u.name} a déjà agi`;document.getElementById('skills-grid').innerHTML='<div class="acted-msg-g">Ce champion a déjà agi ce tour.</div>';return;}

  const def=CHAMPS.find(h=>h.id===u.id);
  if(!def){document.getElementById('sk-header').textContent=`${u.name}`;document.getElementById('skills-grid').innerHTML='<div class="acted-msg-g">Aucune action disponible.</div>';return;}
  const ch=charges[u.id]||0,hasE=getAtkCells(u).length>0;
  document.getElementById('sk-header').textContent=`${u.name} · 💧${u.mp}/${u.maxMp} PM${ch>0?` · ⚡${ch}/3`:''}`;
  const acts=[{...def.basicAttack,isBasic:true},...def.abilities];
  document.getElementById('skills-grid').innerHTML=acts.map((ab,i)=>{
    const ultAlreadyUsed=ab.ult&&ultUsed[u.id];
    if(ab.kind==='place_c4'){const ok2=ab.isBasic||u.mp>=ab.mpCost;return `<button class="sk-btn" ${!ok2?'disabled':''} onclick="useAction(${i})"><span class="sk-type">${ab.type}</span><span class="sk-name">${ab.name}</span><span class="sk-desc">${ab.desc}</span><span class="sk-acc acc-hi">🎯 Port\u00e9e 10</span><span class="sk-cost">PM:${ab.mpCost}${!ok2?` ✗(${u.mp})`:''}</span></button>`;}
    if(ab.kind==='stase_zone'){const ok3=ab.isBasic||u.mp>=ab.mpCost;return `<button class="sk-btn" ${!ok3?'disabled':''} onclick="useAction(${i})"><span class="sk-type">${ab.type}</span><span class="sk-name">${ab.name}</span><span class="sk-desc">${ab.desc}</span><span class="sk-acc acc-hi">🎯 Port\u00e9e 5</span><span class="sk-cost">PM:${ab.mpCost}${!ok3?` ✗(${u.mp})`:''}</span></button>`;}
    if(ab.kind==='transcendance'){const ultUsed4=ab.ult&&ultUsed[u.id];const ok4=(ab.isBasic||u.mp>=ab.mpCost)&&!ultUsed4;return `<button class="sk-btn ult" ${!ok4?'disabled':''} onclick="useAction(${i})"><span class="sk-type">${ab.type}</span><span class="sk-name">${ab.name}</span><span class="sk-desc">${ab.desc}</span>${ultUsed4?'<span class="sk-acc acc-lo">⛔ Déjà utilisé ce combat</span>':'<span class="sk-acc acc-hi">🎯 Auto</span>'}<span class="sk-cost">PM:${ab.mpCost}${!ok4&&!ultUsed4?` ✗(${u.mp})`:''}</span></button>`;}
    const cdLeft=!ab.isBasic&&!ab.ult?getAbilityCD(u.id,i):0;
    const ok=ab.isBasic||u.mp>=ab.mpCost,canUse=ok&&(ab.isSelf||ab.kind==='clone'?true:hasE)&&!ultAlreadyUsed&&cdLeft<=0;
    const isCrit=u.id==='zazura'&&ch>=3&&(ab.kind==='attack'||ab.kind==='double'||ab.isBasic);
    const accV=ab.acc||u.acc,isH=ab.kind==='heal'||ab.kind==='buff'||ab.kind==='clone'||ab.kind==='group_heal';
    if(ab.kind==='needles'){
      const accs=[88,72,55],cA=accs[needles-1];
      return `<button class="sk-btn" ${!canUse?'disabled':''} onclick="useAction(${i})">
        <span class="sk-type">${ab.type}</span><span class="sk-name">${ab.name}</span>
        <div class="needle-ctrl">
          <span class="needle-lbl">×</span>
          <div class="needle-dots">${[1,2,3].map(n=>`<div class="ndot${needles>=n?' on':''}" onclick="setN(${n},event)"></div>`).join('')}</div>
          <span class="needle-acc ${accCls(cA)}">🎯${cA}%</span>
        </div>
        <span class="sk-cost">PM:${ab.mpCost}${!ok?` ✗(${u.mp})`:''}</span>
      </button>`;
    }
    const cdBadge=cdLeft>0?`<span class="sk-acc acc-lo">⏳ ${cdLeft} tour${cdLeft>1?'s':''}</span>`:
      ultAlreadyUsed?'<span class="sk-acc acc-lo">⛔ Déjà utilisé ce combat</span>':
      (!ab.isSelf&&ab.kind!=='clone'?`<span class="sk-acc ${accCls(accV)}">🎯${accV}% ${accLbl(accV)}</span>`:'<span class="sk-acc acc-hi">🎯 Auto</span>');
    return `<button class="sk-btn${ab.ult?' ult':''}${isH?' self-sk':''}${ab.isBasic?' basic-sk':''}" ${!canUse?'disabled':''} onclick="useAction(${i})">
      <span class="sk-type">${ab.type}${isCrit?'<span class="crit-bdg"> ⚡</span>':''}</span>
      <span class="sk-name">${ab.name}</span>
      <span class="sk-desc">${ab.desc}</span>
      ${cdBadge}
      <span class="sk-cost">${ab.isBasic?'Gratuit':`PM:${ab.mpCost}${!ok?` ✗(${u.mp})`:''}`}${!ab.isSelf&&ab.kind!=='clone'&&!hasE&&!ultAlreadyUsed&&cdLeft<=0?' · hors portée':''}</span>
    </button>`;
  }).join('');
}
function setN(n,e){e.stopPropagation();needles=n;if(selUnit)renderSkillBar(selUnit);}

// ══════════════════════════════════════
// ACTIONS
// ══════════════════════════════════════
function getAbilityCD(champId,idx){
  // idx 0=basic(free), 1=sort1(CD1), 2=sort2(CD2), 3=sort3(CD2), 4=ultime(once)
  if(idx===0)return 0;
  return(abilityCooldowns[champId]||{})[idx]||0;
}
function setAbilityCD(champId,idx){
  if(idx===0)return; // no CD on basic attack
  if(!abilityCooldowns[champId])abilityCooldowns[champId]={};
  const cd=idx===1?1:2; // sort1=1T, sorts 2-3=2T, ultime handled by ultUsed
  abilityCooldowns[champId][idx]=cd;
}

function useAction(idx){
  if(!selUnit||phase!=='ally'||selUnit.hasActed)return;
  const def=CHAMPS.find(h=>h.id===selUnit.id)||SUMMON_DEFS[selUnit.id];
  if(!def)return;
  const acts=[{...def.basicAttack,isBasic:true},...def.abilities];
  const ab=acts[idx];
  if(ab.ult&&ultUsed[selUnit.id]){addLog(`⛔ ${ab.name} a déjà été utilisé ce combat !`,'l-miss');return;}
  if(!ab.ult&&idx>0&&getAbilityCD(selUnit.id,idx)>0){addLog(`⏳ ${ab.name} en recharge (${getAbilityCD(selUnit.id,idx)} tour${getAbilityCD(selUnit.id,idx)>1?'s':''})...`,'l-miss');return;}
  if(!ab.isBasic&&selUnit.mp<ab.mpCost)return;
  if(ab.isSelf||ab.kind==='clone'||ab.kind==='summon_wolves'||ab.kind==='place_c4'||ab.kind==='summon_cacahuete'||ab.kind==='mech_suit'){
    // Self-skills complete immediately — set CD here
    if(!ab.ult&&idx>0)setAbilityCD(selUnit.id,idx);
    selfSkill(selUnit,ab);return;
  }
  // Targeted skills: DO NOT set CD here — doFight() will set it once the skill actually fires
  const ac=getAtkCells(selUnit);
  if(!ac.length){addLog('Aucun ennemi à portée','');return;}
  if(ac.length===1){const[r,c]=ac[0];openFight(selUnit,getU(grid[r][c].unit),ab);}
  else{atkCells=ac;draw();addLog('Cliquez sur un ennemi (surligné)','l-sys');canvas._ps=ab;}
}

function selfSkill(u,ab){
  if(ab.ult)ultUsed[u.id]=true;
  if(!ab.isBasic)u.mp=Math.max(0,u.mp-ab.mpCost);
  if(ab.kind==='heal'){const a=Math.floor(u.maxHp*ab.power);u.hp=Math.min(u.maxHp,u.hp+a);addLog(`💚 ${u.name} +${a} PV`,'l-heal');}
  else if(ab.kind==='buff'&&ab.effect==='shield'){shields[u.id]=true;addLog(`🛡️ ${u.name} bouclier !`,'');}
  else if(ab.kind==='dash_shoot'){
    // Pirouette: move 3 cells toward nearest enemy, then shoot
    const nearestEnemy=enemies().reduce((a,b)=>{
      const da=Math.abs(a.row-u.row)+Math.abs(a.col-u.col);
      const db=Math.abs(b.row-u.row)+Math.abs(b.col-u.col);
      return da<db?a:b;
    },enemies()[0]);
    if(nearestEnemy){
      // Move 3 cells toward enemy
      const dr=nearestEnemy.row>u.row?1:nearestEnemy.row<u.row?-1:0;
      const dc=nearestEnemy.col>u.col?1:nearestEnemy.col<u.col?-1:0;
      for(let i=0;i<3;i++){
        const nr=u.row+dr*(i+1),nc=u.col+dc*(i+1);
        if(nr>=0&&nr<ROWS&&nc>=0&&nc<COLS&&!grid[nr][nc].unit&&grid[nr][nc].type!=='mountain'&&grid[nr][nc].type!=='water'){
          grid[u.row][u.col].unit=null;u.row=nr;u.col=nc;grid[nr][nc].unit=u.id;
        } else break;
      }
      u.hasMoved=true;
      // Shoot nearest enemy
      const{result,dmg}=resolveHit(u,ab,nearestEnemy,false);
      if(result!=='miss'){nearestEnemy.hp=Math.max(0,nearestEnemy.hp-dmg);addLog(`🔫 ${u.name} Pirouette → ${nearestEnemy.name}: -${dmg} PV`,'l-dmg');if(nearestEnemy.hp<=0)removeUnit(nearestEnemy);}
      else addLog(`🔫 ${u.name} Pirouette — tir raté !`,'l-miss');
    } else addLog('Aucun ennemi pour Pirouette','');
  }
  else if(ab.kind==='clone'){
    const en=enemies();
    if(en.length){const t=en[Math.floor(Math.random()*en.length)];const d=Math.max(1,Math.floor(u.atk*.6*DMG));t.hp=Math.max(0,t.hp-d);addLog(`👥 Clone→${t.name}: -${d} PV`,'l-dmg');if(t.hp<=0)removeUnit(t);}
    else addLog('👥 Aucune cible pour le clone !','');
  }
  else if(ab.kind==='group_heal'){
    // Heal all allies within radius 2 of Clara
    const radius=2;
    const targets=allies().filter(t=>Math.abs(t.row-u.row)+Math.abs(t.col-u.col)<=radius);
    if(targets.length){
      let names=[];
      targets.forEach(t=>{
        const amt=Math.floor(t.maxHp*ab.power);
        t.hp=Math.min(t.maxHp,t.hp+amt);
        names.push(`${t.name} +${amt}`);
      });
      addLog(`🩸 Rituel Sanguin soigne : ${names.join(', ')} PV`,'l-heal');
    } else {
      addLog('🩸 Aucun allié à portée du Rituel Sanguin','');
    }
  }
  else if(ab.kind==='summon_wolves'){
    // Invoke 2 wolves adjacent to Lestya
    let placed=0;
    const dirs=[[u.row-1,u.col],[u.row+1,u.col],[u.row,u.col-1],[u.row,u.col+1],[u.row-1,u.col-1],[u.row-1,u.col+1],[u.row+1,u.col-1],[u.row+1,u.col+1]];
    for(const[wr,wc] of dirs){
      if(placed>=2)break;
      if(wr<0||wr>=ROWS||wc<0||wc>=COLS)continue;
      if(grid[wr][wc].unit)continue;
      if(grid[wr][wc].type==='mountain'||grid[wr][wc].type==='water'||grid[wr][wc].type==='wall')continue;
      wolfId++;
      const wolf={id:'wolf'+wolfId,name:'Loup',emoji:'🐺',hp:25,maxHp:25,mp:0,maxMp:0,
        atk:Math.floor(u.atk*.7),def:5,spd:90,mov:3,range:1,acc:82,team:'ally',
        effects:[],hasMoved:false,hasActed:false,row:wr,col:wc,isWolf:true};
      units.push(wolf);grid[wr][wc].unit=wolf.id;placed++;
    }
    addLog(`🐺 ${u.name} invoque ${placed} loup${placed>1?'s':''} !`,'l-sys');
  }
  else if(ab.kind==='place_c4'){
    // Enter C4 placement mode — next map click places a trap
    pendingC4=true;
    addLog('💣 Cliquez sur une case vide pour placer le C4','l-sys');
    document.getElementById('sel-lbl').textContent='💣 Choisir emplacement C4';
    // Don't mark hasActed yet — set it after placement
    draw();renderSidebar();renderSkillBar(u);
    return; // Don't mark hasActed or call draw again
  }
  else if(ab.kind==='summon_cacahuete'){
    // Find a 2x2 free area adjacent to Niro
    const spot=find2x2Spot(u.row,u.col);
    if(spot){
      const id='cacahuete1';
      const big={id,name:'Cacahuète',emoji:'🦜',hp:100,maxHp:100,mp:0,maxMp:0,
        atk:Math.floor(u.atk*1.3),def:15,spd:60,mov:2,range:1,acc:80,team:'ally',
        effects:[],hasMoved:false,hasActed:false,row:spot.r,col:spot.c,
        isBig:true,size:2,occupies:[]};
      // Mark 2x2 occupied cells
      for(let dr=0;dr<2;dr++)for(let dc2=0;dc2<2;dc2++){
        const rr=spot.r+dr,cc=spot.c+dc2;
        grid[rr][cc].unit=id;
        big.occupies.push([rr,cc]);
      }
      units.push(big);
      addLog('🦜 Super Cacahuète apparaît, géant et prêt au combat !','l-sys');
    } else {
      addLog('🦜 Pas assez de place pour invoquer Cacahuète !','');
    }
  }
  else if(ab.kind==='mech_suit'){
    // Rokket transforms into the Wreka Suit — replaces him on the map
    const mech={id:u.id,name:'Wreka Suit',emoji:'🤖',hp:150,maxHp:150,mp:0,maxMp:0,
      atk:Math.floor(u.atk*1.4),def:30,spd:50,mov:2,range:3,acc:78,team:'ally',
      effects:[],hasMoved:true,hasActed:true,row:u.row,col:u.col,
      isMech:true,originalName:'Rokket'};
    const idx=units.findIndex(x=>x.id===u.id);
    if(idx>=0)units[idx]=mech;
    addLog('🤖 Rokket embarque dans le Wreka Suit !','l-sys');
    draw();renderSidebar();renderSkillBar(mech);checkWin();
    return;
  }
  else if(ab.kind==='stase_zone'){
    // Enter Stase Corrompue placement mode — next map click marks a zone impassable for 2 turns
    pendingStase=true;
    addLog('🌀 Cliquez sur une case pour figer une zone de corruption','l-sys');
    document.getElementById('sel-lbl').textContent='🌀 Choisir la zone de Stase';
    draw();renderSidebar();renderSkillBar(u);
    return; // Don't mark hasActed yet — set it after placement
  }
  else if(ab.kind==='transcendance'){
    // Corear becomes invulnerable and frozen for 1 turn, then crashes down next turn
    u.transcendState='windup';
    u.transcendTarget=null; // will be chosen when the player picks a landing zone
    shields[u.id]='invuln'; // special marker: full invulnerability, not the normal 45% shield
    pendingTranscendTarget=u.id;
    addLog(`✨ ${u.name} entre en Transcendance — invulnérable, immobile ce tour !`,'l-sys');
    document.getElementById('sel-lbl').textContent='✨ Choisissez la zone d\'impact (au tour suivant)';
  }
  u.hasActed=true;draw();renderSidebar();renderSkillBar(u);checkWin();
}

// Find a free 2x2 area near a given position (for big summons)
function find2x2Spot(nearR,nearC){
  const candidates=[];
  for(let dr=-3;dr<=3;dr++)for(let dc=-3;dc<=3;dc++){
    const r=nearR+dr,c=nearC+dc;
    if(r<0||r+1>=ROWS||c<0||c+1>=COLS)continue;
    let ok=true;
    for(let i=0;i<2&&ok;i++)for(let j=0;j<2&&ok;j++){
      const rr=r+i,cc=c+j;
      if(grid[rr][cc].unit)ok=false;
      if(grid[rr][cc].type==='mountain'||grid[rr][cc].type==='water'||grid[rr][cc].type==='wall')ok=false;
    }
    if(ok)candidates.push({r,c,d:Math.abs(dr)+Math.abs(dc)});
  }
  candidates.sort((a,b)=>a.d-b.d);
  return candidates[0]||null;
}

// ══════════════════════════════════════
// COMBAT
// ══════════════════════════════════════
function openFight(ally,enemy,preSkill){
  cState={ally,enemy};
  document.getElementById('combat-overlay').classList.add('visible');
  buildFightUI(preSkill);
  addLog(`⚔️ ${ally.name} VS ${enemy.name}`,'l-sys');
}
function buildFightUI(pre){
  const{ally:a,enemy:e}=cState;
  const sides=[['fa',a],['fe',e]];
  sides.forEach(([p,u])=>{
    document.getElementById(`${p}-em`).textContent=u.emoji;
    document.getElementById(`${p}-nm`).textContent=u.name;
    document.getElementById(`${p}-hp`).textContent=`❤️${u.hp}/${u.maxHp}`;
    document.getElementById(`${p}-hpbar`).style.width=((u.hp/u.maxHp)*100)+'%';
    document.getElementById(`${p}-mp`).textContent=`💧${u.mp}/${u.maxMp}`;
    document.getElementById(`${p}-mpbar`).style.width=((u.mp/u.maxMp)*100)+'%';
  });
  document.getElementById('cb-log').textContent='Choisissez une action...';
  document.getElementById('cb-log').className='cb-log';
  const def=CHAMPS.find(h=>h.id===a.id)||SUMMON_DEFS[a.id];
  if(!def){closeFight();return;} // Safety: should never happen for player-controlled units
  const ch=charges[a.id]||0;
  const allActs=[{...def.basicAttack,isBasic:true,origIdx:0},...(def.abilities||[]).map((x,j)=>({...x,origIdx:j+1}))];
  const acts=allActs.filter(x=>!x.isSelf&&x.kind!=='clone'&&x.kind!=='summon_wolves'&&x.kind!=='place_c4');
  document.getElementById('fight-actions').innerHTML=acts.map((ab,i)=>{
    const isCrit=a.id==='zazura'&&ch>=3&&(ab.kind==='attack'||ab.kind==='double'||ab.isBasic);
    const accV=ab.kind==='needles'?[88,72,55][needles-1]:(ab.acc||a.acc);
    const noMp=!ab.isBasic&&a.mp<ab.mpCost;
    const ultAlreadyUsed=ab.ult&&ultUsed[a.id];
    const cdLeft=!ab.isBasic&&!ab.ult?getAbilityCD(a.id,ab.origIdx):0;
    const lbl=ab.kind==='needles'?`Aiguilles ×${needles}`:ab.name;
    const disabled=(noMp||ultAlreadyUsed||cdLeft>0)?'disabled':'';
    return `<button class="fa-btn${ab.ult?' ult':''}${ab.isBasic?' basic-fa':''}" ${disabled} onclick="doFight(${i},${ab.origIdx})">
      <span class="sk-type">${ab.type}${isCrit?' ⚡':''} · ${ab.isBasic?'Gratuit':`PM:${ab.mpCost}${noMp?' ✗':''}`}</span>
      <span class="sk-name">${lbl}</span>
      <span class="sk-desc">${ab.desc}</span>
      ${ultAlreadyUsed?'<span class="fa-acc acc-lo">⛔ Déjà utilisé</span>':cdLeft>0?`<span class="fa-acc acc-lo">⏳ ${cdLeft} tour${cdLeft>1?'s':''}</span>`:`<span class="fa-acc ${accCls(accV)}">🎯${accV}%</span>`}
    </button>`;
  }).join('');
  if(pre&&!pre.isSelf&&pre.kind!=='clone'){const i=acts.findIndex(a2=>a2.name===pre.name);const origI=i>=0?acts[i].origIdx:0;if(i>=0&&!(acts[i].ult&&ultUsed[a.id])&&getAbilityCD(a.id,origI)<=0)setTimeout(()=>doFight(i,origI),100);}
}

function updateFightStats(){
  const{ally:a,enemy:e}=cState;
  const sides=[['fa',a],['fe',e]];
  sides.forEach(([p,u])=>{
    document.getElementById(`${p}-hp`).textContent=`❤️${u.hp}/${u.maxHp}`;
    document.getElementById(`${p}-hpbar`).style.width=Math.max(0,(u.hp/u.maxHp)*100)+'%';
    document.getElementById(`${p}-mp`).textContent=`💧${u.mp}/${u.maxMp}`;
    document.getElementById(`${p}-mpbar`).style.width=Math.max(0,(u.mp/u.maxMp)*100)+'%';
  });
}

function doFight(idx,origIdx){
  const{ally:a,enemy:e}=cState;
  const def=CHAMPS.find(h=>h.id===a.id)||SUMMON_DEFS[a.id];
  if(!def){closeFight();return;}
  const acts=[{...def.basicAttack,isBasic:true},...(def.abilities||[]).filter(x=>!x.isSelf&&x.kind!=='clone'&&x.kind!=='summon_wolves'&&x.kind!=='place_c4')];
  const ab=acts[idx];
  if(ab.ult&&ultUsed[a.id])return;
  if(ab.ult)ultUsed[a.id]=true;
  // Apply ability cooldown for non-basic, non-ult abilities
  if(!ab.isBasic&&!ab.ult&&origIdx>0)setAbilityCD(a.id,origIdx);
  // Ekal's Énergivore passif: fatigue increases MP cost every 2 casts
  let effectiveCost=ab.mpCost||0;
  if(a.id==='ekal'&&!ab.isBasic){
    charges['ekal_casts']=(charges['ekal_casts']||0)+1;
    const fatigueStacks=Math.floor(charges['ekal_casts']/2);
    effectiveCost+=fatigueStacks*5;
  }
  if(!ab.isBasic&&a.mp<effectiveCost)return;
  if(!ab.isBasic)a.mp=Math.max(0,a.mp-effectiveCost);
  const ch=charges[a.id]||0,isCrit=a.id==='zazura'&&ch>=3;
  if(isCrit)charges[a.id]=0;
  document.getElementById('fight-actions').querySelectorAll('button').forEach(b=>b.disabled=true);
  let lc='',lm='';

  if(ab.kind==='wave'){
    // Onde Résonnante: hits up to 3 enemies in a line/cone around target
    const range=ab.range||3;
    // Find all enemies within range of Achlys (not just target)
    const targets=[];
    for(let dr=-range;dr<=range;dr++)for(let dc2=-range;dc2<=range;dc2++){
      const d=Math.abs(dr)+Math.abs(dc2);if(!d||d>range)continue;
      const nr=a.row+dr,nc=a.col+dc2;
      if(nr<0||nr>=ROWS||nc<0||nc>=COLS)continue;
      if(grid[nr][nc].unit){const o=getU(grid[nr][nc].unit);if(o&&o.team!=='ally'&&o.hp>0)targets.push(o);}
    }
    const hits=targets.slice(0,3); // max 3
    let tot=0,names=[];
    hits.forEach(t=>{
      const{result,dmg}=resolveHit(a,ab,t,false);
      if(result!=='miss'){t.hp=Math.max(0,t.hp-dmg);tot+=dmg;names.push(`${t.name} -${dmg}`);}
    });
    lm=names.length>0?`Onde frappe : ${names.join(', ')} PV.`:`Onde ne touche personne !`;
    lc=names.length>0?'lc-dmg':'lc-miss';
    addLog(`✨ Onde Résonnante → ${names.length} cibles`,'l-sys');
    // Remove dead
    hits.forEach(t=>{if(t.hp<=0)removeUnit(t);});
    a.hasActed=true;document.getElementById('cb-log').textContent=lm;document.getElementById('cb-log').className='cb-log '+lc;
    updateFightStats();draw();renderSidebar();setTimeout(()=>checkFightEnd(),400);return;
  }

  if(ab.kind==='oneshot3'){
    // Forme Finale: one-shot up to 3 enemies within range 2 of Achlys
    const range=ab.range||2;
    const targets=[];
    for(let dr=-range;dr<=range;dr++)for(let dc2=-range;dc2<=range;dc2++){
      const d=Math.abs(dr)+Math.abs(dc2);if(!d||d>range)continue;
      const nr=a.row+dr,nc=a.col+dc2;
      if(nr<0||nr>=ROWS||nc<0||nc>=COLS)continue;
      if(grid[nr][nc].unit){const o=getU(grid[nr][nc].unit);if(o&&o.team!=='ally'&&o.hp>0)targets.push(o);}
    }
    const victims=targets.slice(0,3);
    const killed=[];
    victims.forEach(t=>{t.hp=0;killed.push(t.name);grid[t.row][t.col].unit=null;});
    units=units.filter(u=>u.hp>0||u.team==='ally');
    lm=killed.length>0?`⚡ Forme Finale pétrifie : ${killed.join(', ')} !`:`Aucune cible assez proche !`;
    lc=killed.length>0?'lc-crit':'lc-miss';
    addLog(`💎 Forme Finale — ${killed.length} cibles pétrifiées !`,'l-sys');
    a.hasActed=true;document.getElementById('cb-log').textContent=lm;document.getElementById('cb-log').className='cb-log '+lc;
    updateFightStats();draw();renderSidebar();setTimeout(()=>checkFightEnd(),400);return;
  }

  if(ab.kind==='synapse'){
    // Synapse: explosion around target (radius 2)
    const radius=2;
    const targets=[];
    for(let dr=-radius;dr<=radius;dr++)for(let dc2=-radius;dc2<=radius;dc2++){
      const d=Math.abs(dr)+Math.abs(dc2);if(!d||d>radius)continue;
      const nr=e.row+dr,nc=e.col+dc2;
      if(nr<0||nr>=ROWS||nc<0||nc>=COLS)continue;
      if(grid[nr][nc].unit){const o=getU(grid[nr][nc].unit);if(o&&o.team!=='ally'&&o.hp>0)targets.push(o);}
    }
    targets.push(e); // always hit primary target
    const unique=[...new Map(targets.map(t=>[t.id,t])).values()];
    let tot=0,names=[];
    unique.forEach(t=>{
      const{result,dmg}=resolveHit(a,ab,t,false);
      if(result!=='miss'){t.hp=Math.max(0,t.hp-dmg);tot+=dmg;names.push(`${t.name} -${dmg}`);}
    });
    lm=`Synapse explose : ${names.join(', ')} PV !`;lc='lc-dmg';
    addLog(`🌀 Synapse → explosion sur ${unique.length} cibles`,'l-sys');
    unique.forEach(t=>{if(t.hp<=0)removeUnit(t);});
    a.hasActed=true;document.getElementById('cb-log').textContent=lm;document.getElementById('cb-log').className='cb-log '+lc;
    updateFightStats();draw();renderSidebar();setTimeout(()=>checkFightEnd(),400);return;
  }

  if(ab.kind==='needles'){
    const accs=[88,72,55],cA=accs[needles-1];
    let tot=0,hits=0;
    for(let i=0;i<needles;i++){const r=roll(cA,0);if(r!=='miss'){let d=Math.floor(a.atk*ab.power*DMG*(.88+Math.random()*.25));if(r==='crit')d*=2;d=Math.max(1,d-Math.floor((e.def||0)*.35));const pr=petriciteReduction(e.row,e.col);if(pr>0)d=Math.max(1,Math.floor(d*(1-pr)));e.hp=Math.max(0,e.hp-d);tot+=d;hits++;}}
    lm=hits>0?`${hits}/${needles} aiguilles : -${tot} PV.`:'Toutes ratent !';lc=hits>0?'lc-dmg':'lc-miss';
    addLog(`🌀 ${hits}/${needles} aiguilles → -${tot}`,'l-dmg');
  } else if(ab.kind==='double'){
    let tot=0,msgs=[];
    for(let i=0;i<2;i++){const{result,dmg}=resolveHit(a,ab,e,isCrit&&i===0);if(result==='miss')msgs.push('raté');else{e.hp=Math.max(0,e.hp-dmg);tot+=dmg;msgs.push(`-${dmg}${result==='crit'?' CRIT':''}`);}};
    lm=`2× : ${msgs.join(', ')}`;lc=tot>0?'lc-dmg':'lc-miss';
    if(!isCrit)charges[a.id]=(charges[a.id]||0)+1;
  } else if(ab.kind==='drain'){
    const{result,dmg}=resolveHit(a,ab,e,false);
    if(result==='miss'){lm='Transfusion rate !';lc='lc-miss';}
    else{e.hp=Math.max(0,e.hp-dmg);const ht=allies().reduce((x,y)=>x.hp<y.hp?x:y);const ha=Math.floor(dmg*.6);ht.hp=Math.min(ht.maxHp,ht.hp+ha);lm=`Transfusion : -${dmg}/${e.name}, +${ha}/${ht.name}`;lc='lc-dmg';addLog(`🩸 -${dmg}/+${ha}`,'l-heal');}
  } else if(ab.kind==='pull'){
    const{result,dmg}=resolveHit(a,ab,e,false);
    if(result==='miss'){lm=`${a.name} rate ses Lames Enchaînées !`;lc='lc-miss';addLog('💨 Lames Enchaînées ratées !','l-miss');}
    else{
      e.hp=Math.max(0,e.hp-dmg);
      // Pull enemy 2 cells toward Varesh (opposite direction of knockback)
      let pulled=0;
      for(let i=0;i<2;i++){
        const dr=e.row>a.row?-1:e.row<a.row?1:0;
        const dc2=e.col>a.col?-1:e.col<a.col?1:0;
        if(dr===0&&dc2===0)break;
        const nr=e.row+dr,nc=e.col+dc2;
        if(nr<0||nr>=ROWS||nc<0||nc>=COLS)break;
        if(grid[nr][nc].unit)break;
        if(grid[nr][nc].type==='mountain'||grid[nr][nc].type==='water'||grid[nr][nc].type==='wall')break;
        clearUnitCells(e);e.row=nr;e.col=nc;grid[nr][nc].unit=e.id;pulled++;
      }
      lm=`${a.name} inflige ${dmg} PV et attire ${e.name} de ${pulled} case${pulled>1?'s':''} !`;
      lc='lc-dmg';
      addLog(`🔗 Lames Enchaînées → ${e.name} -${dmg} PV, attiré`,'l-dmg');
    }
  } else if(ab.kind==='teleport_strike'){
    // Teleport adjacent to target, then strike
    const adjSpots=[[e.row-1,e.col],[e.row+1,e.col],[e.row,e.col-1],[e.row,e.col+1]]
      .filter(([nr,nc])=>nr>=0&&nr<ROWS&&nc>=0&&nc<COLS&&!grid[nr][nc].unit&&grid[nr][nc].type!=='mountain'&&grid[nr][nc].type!=='water'&&grid[nr][nc].type!=='wall');
    if(adjSpots.length){
      const[nr,nc]=adjSpots[0];
      clearUnitCells(a);a.row=nr;a.col=nc;grid[nr][nc].unit=a.id;
    }
    const{result,dmg}=resolveHit(a,ab,e,false);
    if(result==='miss'){lm=`${a.name} se téléporte mais rate son attaque !`;lc='lc-miss';addLog('💨 Bond Éthéré — attaque ratée','l-miss');}
    else{
      e.hp=Math.max(0,e.hp-dmg);
      lm=`${a.name} bondit et frappe ${e.name} : -${dmg} PV !`;lc='lc-dmg';
      addLog(`👤 Bond Éthéré → ${e.name} -${dmg} PV`,'l-dmg');
    }
  } else if(ab.kind==='impale10'){
    // Hit up to 10 enemies within range 3, one by one
    const range=3;
    const targets=[];
    for(let dr=-range;dr<=range;dr++)for(let dc2=-range;dc2<=range;dc2++){
      const d=Math.abs(dr)+Math.abs(dc2);if(!d||d>range)continue;
      const nr=a.row+dr,nc=a.col+dc2;
      if(nr<0||nr>=ROWS||nc<0||nc>=COLS)continue;
      if(grid[nr][nc].unit){const o=getU(grid[nr][nc].unit);if(o&&o.team!=='ally'&&o.hp>0)targets.push(o);}
    }
    const victims=targets.slice(0,10);
    let tot=0,names=[];
    victims.forEach(t=>{
      const{result,dmg}=resolveHit(a,ab,t,false);
      if(result!=='miss'){t.hp=Math.max(0,t.hp-dmg);tot+=dmg;names.push(`${t.name} -${dmg}`);}
    });
    lm=names.length>0?`Empalement traverse ${victims.length} ennemis : ${names.join(', ')} PV !`:`Aucun ennemi à portée !`;
    lc=names.length>0?'lc-crit':'lc-miss';
    addLog(`🗲 Empalement Imprévisible → ${names.length}/${victims.length} touchés`,'l-sys');
    victims.forEach(t=>{if(t.hp<=0)removeUnit(t);});
  } else if(ab.kind==='dash_line'){
    // Ruée Corrompue: dash up to 4 cells toward target, hitting everyone in the path.
    // Damage is reduced based on how many targets are hit (more targets = less dmg each).
    const dr=e.row>a.row?1:e.row<a.row?-1:0;
    const dc2=e.col>a.col?1:e.col<a.col?-1:0;
    const path=[];
    let cr=a.row,cc=a.col;
    for(let i=0;i<4;i++){
      const nr=cr+dr,nc=cc+dc2;
      if(nr<0||nr>=ROWS||nc<0||nc>=COLS)break;
      if(grid[nr][nc].type==='mountain'||grid[nr][nc].type==='water'||grid[nr][nc].type==='wall')break;
      path.push({r:nr,c:nc});
      cr=nr;cc=nc;
    }
    // Collect enemies along the path
    const hitTargets=[];
    path.forEach(p=>{
      if(grid[p.r][p.c].unit){const o=getU(grid[p.r][p.c].unit);if(o&&o.team!=='ally'&&o.hp>0)hitTargets.push(o);}
    });
    const reduction=Math.max(0.4,1-(hitTargets.length-1)*0.2); // more targets = less dmg each, floor at 40%
    let tot=0,names=[];
    hitTargets.forEach(t=>{
      const{result,dmg}=resolveHit(a,{...ab,power:ab.power*reduction},t,false);
      if(result!=='miss'){t.hp=Math.max(0,t.hp-dmg);tot+=dmg;names.push(`${t.name} -${dmg}`);}
    });
    // Move Corear to the furthest free cell reached in the dash
    let dest=null;
    for(let i=path.length-1;i>=0;i--){
      if(!grid[path[i].r][path[i].c].unit||path[i].r===e.row&&path[i].c===e.col){dest=path[i];break;}
    }
    if(dest&&!grid[dest.r][dest.c].unit){clearUnitCells(a);a.row=dest.r;a.col=dest.c;grid[dest.r][dest.c].unit=a.id;}
    lm=names.length>0?`Ruée Corrompue traverse ${hitTargets.length} cible(s) : ${names.join(', ')} PV !`:`La ruée ne touche personne !`;
    lc=names.length>0?'lc-dmg':'lc-miss';
    addLog(`⚔️ Ruée Corrompue → ${hitTargets.length} cible(s), -${tot} PV total`,'l-dmg');
    hitTargets.forEach(t=>{if(t.hp<=0)removeUnit(t);});
  } else if(ab.kind==='darkin_lance'){
    // Hit primary target, then teleport to strike the 2nd closest enemy
    const{result,dmg}=resolveHit(a,ab,e,false);
    let msg='';
    if(result==='miss'){msg=`${a.name} rate sa Lance Darkin sur ${e.name} !`;}
    else{e.hp=Math.max(0,e.hp-dmg);msg=`Lance Darkin frappe ${e.name} : -${dmg} PV.`;if(e.hp<=0)removeUnit(e);}
    // Find the 2nd closest enemy (excluding the primary target)
    const remaining=enemies().filter(en=>en.id!==e.id);
    if(remaining.length){
      const second=remaining.reduce((x,y)=>
        Math.abs(x.row-a.row)+Math.abs(x.col-a.col)<Math.abs(y.row-a.row)+Math.abs(y.col-a.col)?x:y
      );
      const adjSpots=[[second.row-1,second.col],[second.row+1,second.col],[second.row,second.col-1],[second.row,second.col+1]]
        .filter(([nr,nc])=>nr>=0&&nr<ROWS&&nc>=0&&nc<COLS&&!grid[nr][nc].unit&&grid[nr][nc].type!=='mountain'&&grid[nr][nc].type!=='water'&&grid[nr][nc].type!=='wall');
      if(adjSpots.length){
        const[nr,nc]=adjSpots[0];
        clearUnitCells(a);a.row=nr;a.col=nc;grid[nr][nc].unit=a.id;
        const hit2=resolveHit(a,ab,second,false);
        if(hit2.result==='miss'){msg+=` Corear se téléporte vers ${second.name} mais rate !`;}
        else{second.hp=Math.max(0,second.hp-hit2.dmg);msg+=` Téléportation → ${second.name} : -${hit2.dmg} PV !`;if(second.hp<=0)removeUnit(second);}
      } else {
        msg+=` Aucune position libre près de ${second.name} pour se téléporter.`;
      }
    }
    lm=msg;lc='lc-dmg';
    addLog(`🗡️ ${msg}`,'l-dmg');
  } else if(ab.kind==='knockback'){
    const{result,dmg}=resolveHit(a,ab,e,false);
    if(result==='miss'){lm=`${a.name} rate l'Impulsion !`;lc='lc-miss';addLog('💨 Impulsion ratée !','l-miss');}
    else{
      e.hp=Math.max(0,e.hp-dmg);
      // Push enemy 2 cells away from Ekal
      const dr=e.row>a.row?1:e.row<a.row?-1:0;
      const dc2=e.col>a.col?1:e.col<a.col?-1:0;
      let pushed=0;
      for(let i=0;i<2;i++){
        const nr=e.row+dr,nc=e.col+dc2;
        if(nr<0||nr>=ROWS||nc<0||nc>=COLS)break;
        if(grid[nr][nc].unit)break;
        if(grid[nr][nc].type==='mountain'||grid[nr][nc].type==='water'||grid[nr][nc].type==='wall')break;
        clearUnitCells(e);e.row=nr;e.col=nc;grid[nr][nc].unit=e.id;pushed++;
      }
      lm=`${a.name} inflige ${dmg} PV et repousse ${e.name} de ${pushed} case${pushed>1?'s':''} !`;
      lc='lc-dmg';
      addLog(`🌀 Impulsion → ${e.name} -${dmg} PV, repoussé`,'l-dmg');
    }
  } else if(ab.kind==='aoe'){
    // True AoE: hits target + all enemies within radius 1 of target
    const radius=1;
    const targets=[];
    for(let dr=-radius;dr<=radius;dr++)for(let dc2=-radius;dc2<=radius;dc2++){
      const nr=e.row+dr,nc=e.col+dc2;
      if(nr<0||nr>=ROWS||nc<0||nc>=COLS)continue;
      if(grid[nr][nc].unit){const o=getU(grid[nr][nc].unit);if(o&&o.team!=='ally'&&o.hp>0)targets.push(o);}
    }
    const unique2=[...new Map(targets.map(t=>[t.id,t])).values()];
    let tot=0,names=[];
    unique2.forEach(t=>{
      const{result,dmg}=resolveHit(a,ab,t,isCrit);
      if(result!=='miss'){
        t.hp=Math.max(0,t.hp-dmg);tot+=dmg;names.push(`${t.name} -${dmg}`);
        const fx=ab.effect;
        if(fx==='stun')t.effects.push({type:'stun',turns:2});
        if(fx==='stun3')t.effects.push({type:'stun',turns:3});
        if(fx==='shred')t.def=Math.max(0,(t.def||0)-15);
      }
    });
    lm=names.length>0?`${ab.name} frappe : ${names.join(', ')} PV !`:`${ab.name} ne touche personne !`;
    lc=names.length>0?'lc-dmg':'lc-miss';
    addLog(`💥 ${ab.name} → ${unique2.length} cibles, -${tot} PV total`,'l-dmg');
    unique2.forEach(t=>{if(t.hp<=0)removeUnit(t);});
  } else {
    // Arme Éthérée (ignore_armor): bypass target's DEF entirely
    const ignoreArmor=ab.effect==='ignore_armor';
    const origDef=e.def;
    if(ignoreArmor)e.def=0;
    const{result,dmg}=resolveHit(a,ab,e,isCrit);
    if(ignoreArmor)e.def=origDef;
    if(result==='miss'){lm=`${a.name} rate !`;lc='lc-miss';addLog(`💨 rate !`,'l-miss');}
    else{
      e.hp=Math.max(0,e.hp-dmg);
      lm=`${result==='crit'?'⚡ CRIT ! ':''}${a.name} inflige ${dmg} PV.${ignoreArmor?' Armure ignorée !':''}`;
      lc=result==='crit'?'lc-crit':'lc-dmg';
      addLog(`${result==='crit'?'💥':'⚔️'} ${a.name}→${e.name}: -${dmg} PV${ignoreArmor?' (armure ignorée)':''}`,'l-dmg');
      const fx=ab.effect;
      if(fx==='stun'&&result!=='miss')e.effects.push({type:'stun',turns:1});
      if(fx==='stun2'&&result!=='miss'){e.effects.push({type:'stun',turns:2});lm+=' Gravité désactivée — immobilisé 2 tours !';}
      if(fx==='charm'&&result!=='miss'){e.effects.push({type:'stun',turns:1});lm+=` 💋 Charmé !`;}
      if(fx==='shadow_charge')charges[a.id]=(charges[a.id]||0)+1;
      if(fx==='shadow_charge_move'){charges[a.id]=(charges[a.id]||0)+1;a.hasMoved=false;mvCells=getMovCells(a);lm+=' Zazura peut se déplacer à nouveau !';addLog('💨 Frappe d\'ombre — déplacement supplémentaire accordé !','l-sys');}
      if(fx==='immobilize'&&result!=='miss'){e.effects.push({type:'immobilize',turns:2});lm+=' 🌿 Enraciné — ne peut plus se déplacer pendant 2 tours !';}
      if(fx==='statue'&&result!=='miss')e.effects.push({type:'statue',turns:2});
      if(fx==='shred'){e.def=Math.max(0,(e.def||0)-15);lm+=' Défenses brisées !';}
      if(fx==='poison'&&result!=='miss')e.effects.push({type:'poison',turns:3,dmg:8});
      if(fx==='lifesteal'&&result!=='miss'){const h=Math.floor(dmg*.3);a.hp=Math.min(a.maxHp,a.hp+h);lm+=` (+${h} PV)`;}
    }
  }
  if(a.id==='clara'&&Math.random()<.25&&e.hp>0){e.effects.push({type:'stun',turns:1});lm+=' 💋 Charme passif !';}

  const lg=document.getElementById('cb-log');lg.textContent=lm;lg.className='cb-log '+lc;
  a.hasActed=true;updateFightStats();draw();renderSidebar();
  setTimeout(()=>checkFightEnd(),600);
}

function checkFightEnd(){
  const{ally:a,enemy:e}=cState;
  if(e.hp<=0){
    addLog(`☠️ ${e.name} vaincu !`,'l-sys');
    if(e.isBoss)addLog('✦ L\'aura disparaît ! Les bandits affaiblis.','l-sys');
    removeUnit(e);
    closeFight();checkWin();
  } else if(a.hp<=0){
    addLog(`💀 ${a.name} tombé !`,'l-sys');
    removeUnit(a);
    closeFight();selUnit=null;renderSkillBar(null);checkLose();
  }
}
function closeFight(){cState=null;canvas._ps=null;document.getElementById('combat-overlay').classList.remove('visible');mvCells=[];atkCells=selUnit?getAtkCells(selUnit):[];draw();renderSidebar();if(selUnit)renderSkillBar(selUnit);}
function fleeCombat(){addLog('↩ Repli tactique','');closeFight();}

// ══════════════════════════════════════
// SELECT UNIT
// ══════════════════════════════════════
function selectU(id){
  const u=getU(id);if(!u||u.hp<=0)return;
  if(u.team!==phase){addLog('Pas votre phase !','');return;}
  selUnit=u;
  if(u.isWolf){mvCells=[];atkCells=[];} // wolves stay fully auto-controlled
  else{mvCells=u.hasMoved?[]:getMovCells(u);atkCells=getAtkCells(u);}
  canvas._ps=null;needles=1;
  document.getElementById('sel-lbl').textContent=`${u.emoji} ${u.name}`;
  renderSkillBar(u);renderSidebar();draw();
  const mw=document.getElementById('map-wrap');mw.scrollLeft=Math.max(0,u.col*CELL-mw.clientWidth/2);mw.scrollTop=Math.max(0,u.row*CELL-mw.clientHeight/2);
}

canvas.addEventListener('click',ev=>{
  if(cState||phase!=='ally')return;
  const rect=canvas.getBoundingClientRect();
  const col=Math.floor((ev.clientX-rect.left)*(canvas.width/rect.width)/CELL);
  const row=Math.floor((ev.clientY-rect.top)*(canvas.height/rect.height)/CELL);
  if(col<0||col>=COLS||row<0||row>=ROWS)return;

  // ── C4 PLACEMENT MODE ──
  if(pendingC4&&selUnit){
    const distFromVoss=Math.abs(row-selUnit.row)+Math.abs(col-selUnit.col);
    if(distFromVoss>10){
      addLog('💣 Trop loin — portée maximale 10 cases','l-miss');
      return;
    }
    if(!grid[row][col].unit&&grid[row][col].type!=='mountain'&&grid[row][col].type!=='water'&&grid[row][col].type!=='wall'){
      c4Traps.push({row,col,ownerId:selUnit.id,atk:selUnit.atk});
      pendingC4=false;
      selUnit.hasActed=true;
      addLog(`💣 C4 posé en (${row},${col}) — attend une cible !`,'l-sys');
      document.getElementById('sel-lbl').textContent=`${selUnit.emoji} ${selUnit.name}`;
      draw();renderSidebar();renderSkillBar(selUnit);
    } else {
      addLog('💣 Case invalide pour le C4','');
    }
    return;
  }

  // ── STASE CORROMPUE PLACEMENT MODE ──
  if(pendingStase&&selUnit){
    const distFromCorear=Math.abs(row-selUnit.row)+Math.abs(col-selUnit.col);
    if(distFromCorear>5){
      addLog('🌀 Trop loin — portée maximale 5 cases','l-miss');
      return;
    }
    staseZones.push({row,col,turns:2});
    pendingStase=false;
    selUnit.hasActed=true;
    addLog(`🌀 ${selUnit.name} fige une zone de corruption en (${row},${col}) pendant 2 tours !`,'l-sys');
    document.getElementById('sel-lbl').textContent=`${selUnit.emoji} ${selUnit.name}`;
    draw();renderSidebar();renderSkillBar(selUnit);
    return;
  }

  // ── TRANSCENDANCE LANDING TARGET SELECTION ──
  if(pendingTranscendTarget&&selUnit&&selUnit.id===pendingTranscendTarget){
    selUnit.transcendLandRow=row;
    selUnit.transcendLandCol=col;
    pendingTranscendTarget=null;
    addLog(`✨ ${selUnit.name} vise une zone d'impact — l'atterrissage aura lieu au prochain tour !`,'l-sys');
    document.getElementById('sel-lbl').textContent=`${selUnit.emoji} ${selUnit.name}`;
    draw();renderSidebar();renderSkillBar(selUnit);
    return;
  }

  const clicked=grid[row][col].unit?getU(grid[row][col].unit):null;
  if(clicked&&clicked.team==='ally'&&clicked.hp>0){selectU(clicked.id);return;}
  if(!selUnit)return;
  // Wolves stay fully auto-controlled — cannot be manually moved or attack
  if(selUnit.isWolf)return;
  if(clicked&&clicked.team==='enemy'&&clicked.hp>0){
    if(selUnit.hasActed){addLog(`${selUnit.name} a déjà agi !`,'');return;}
    const inAtk=atkCells.find(([r,c])=>r===row&&c===col);
    if(inAtk){const sk=canvas._ps;canvas._ps=null;openFight(selUnit,clicked,sk);}
    else addLog('Hors de portée','');
    return;
  }
  if(!clicked){
    if(selUnit.hasMoved){addLog(`${selUnit.name} a déjà bougé !`,'');return;}
    const inMov=mvCells.find(([r,c])=>r===row&&c===col);
    if(inMov){
      if(selUnit.isBig){
        clearUnitCells(selUnit);
        selUnit.row=row;selUnit.col=col;
        selUnit.occupies=[];
        for(let dr=0;dr<2;dr++)for(let dc2=0;dc2<2;dc2++){
          const rr=row+dr,cc=col+dc2;
          grid[rr][cc].unit=selUnit.id;
          selUnit.occupies.push([rr,cc]);
        }
      } else {
        grid[selUnit.row][selUnit.col].unit=null;selUnit.row=row;selUnit.col=col;grid[row][col].unit=selUnit.id;
      }
      selUnit.hasMoved=true;mvCells=[];atkCells=getAtkCells(selUnit);
      addLog(`${selUnit.emoji} ${selUnit.name} se déplace`,'l-move');
      renderSidebar();renderSkillBar(selUnit);draw();
      // Check fuite AFTER move is applied
      if(opActive&&opStage===0)checkFuiteOp(selUnit);
    }
  }
});

